import React, { useState } from 'react';

// Integrated modern styles for Vighnex Technologies
const styles = `
  @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap');

  :root {
    --primary: #4F46E5;
    --primary-hover: #4338CA;
    --secondary: #06B6D4;
    --accent: #F43F5E;
    --dark-bg: #0F172A;
    --card-bg: #1E293B;
    --text-main: #F8FAFC;
    --text-muted: #94A3B8;
    --border: #334155;
    --gradient-primary: linear-gradient(135deg, #4F46E5 0%, #06B6D4 100%);
    --gradient-text: linear-gradient(135deg, #818CF8 0%, #38BDF8 100%);
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    font-family: 'Plus Jakarta Sans', sans-serif;
  }

  body {
    background-color: var(--dark-bg);
    color: var(--text-main);
    line-height: 1.6;
    overflow-x: hidden;
  }

  /* Header / Navbar */
  .navbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.25rem 5%;
    background: rgba(15, 23, 42, 0.85);
    backdrop-filter: blur(12px);
    position: sticky;
    top: 0;
    z-index: 1000;
    border-bottom: 1px solid var(--border);
  }

  .brand-logo {
    font-size: 1.6rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: var(--text-main);
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
  }

  .brand-logo span {
    background: var(--gradient-text);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .nav-links {
    display: flex;
    gap: 2rem;
    list-style: none;
  }

  .nav-btn {
    background: none;
    border: none;
    color: var(--text-muted);
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.3s ease;
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
  }

  .nav-btn:hover, .nav-btn.active {
    color: var(--text-main);
    background: rgba(255, 255, 255, 0.05);
  }

  .nav-btn.active {
    color: #38BDF8;
    font-weight: 600;
  }

  .btn-cta {
    background: var(--gradient-primary);
    color: white;
    font-weight: 600;
    padding: 0.75rem 1.5rem;
    border-radius: 8px;
    border: none;
    cursor: pointer;
    box-shadow: 0 4px 14px rgba(79, 70, 229, 0.35);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
  }

  .btn-cta:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(79, 70, 229, 0.5);
  }

  /* Hero Section */
  .hero-section {
    padding: 6rem 5% 4rem;
    text-align: center;
    position: relative;
    background: radial-gradient(circle at 50% 20%, rgba(79, 70, 229, 0.15) 0%, transparent 70%);
  }

  .badge {
    display: inline-block;
    padding: 0.4rem 1rem;
    background: rgba(79, 70, 229, 0.15);
    border: 1px solid rgba(129, 140, 248, 0.3);
    border-radius: 50px;
    color: #818CF8;
    font-size: 0.875rem;
    font-weight: 600;
    margin-bottom: 1.5rem;
  }

  .hero-title {
    font-size: 3.5rem;
    font-weight: 800;
    line-height: 1.15;
    margin-bottom: 1.5rem;
    letter-spacing: -1px;
  }

  .hero-subtitle {
    font-size: 1.25rem;
    color: var(--text-muted);
    max-width: 750px;
    margin: 0 auto 2.5rem;
  }

  .hero-buttons {
    display: flex;
    justify-content: center;
    gap: 1.25rem;
  }

  .btn-outline {
    background: transparent;
    border: 1px solid var(--border);
    color: var(--text-main);
    font-weight: 600;
    padding: 0.75rem 1.5rem;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
  }

  .btn-outline:hover {
    background: rgba(255, 255, 255, 0.05);
    border-color: var(--text-muted);
  }

  /* Section Styling */
  .section-container {
    padding: 5rem 5%;
    max-width: 1280px;
    margin: 0 auto;
  }

  .section-header {
    text-align: center;
    margin-bottom: 3.5rem;
  }

  .section-title {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 0.75rem;
  }

  .section-subtitle {
    color: var(--text-muted);
    font-size: 1.1rem;
    max-width: 600px;
    margin: 0 auto;
  }

  /* Services Cards Grid */
  .services-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(270px, 1fr));
    gap: 2rem;
  }

  .service-card {
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 2.25rem;
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden;
  }

  .service-card:hover {
    transform: translateY(-6px);
    border-color: #4F46E5;
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.3);
  }

  .service-icon {
    width: 60px;
    height: 60px;
    border-radius: 12px;
    background: rgba(79, 70, 229, 0.1);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.8rem;
    margin-bottom: 1.5rem;
    color: #38BDF8;
  }

  .service-card h3 {
    font-size: 1.35rem;
    margin-bottom: 1rem;
  }

  .service-card p {
    color: var(--text-muted);
    font-size: 0.95rem;
    line-height: 1.6;
  }

  /* About Us Page Layout */
  .about-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
  }

  .about-content h2 {
    font-size: 2.25rem;
    margin-bottom: 1.25rem;
  }

  .about-content p {
    color: var(--text-muted);
    margin-bottom: 1.25rem;
    font-size: 1.05rem;
  }

  .stats-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 1.5rem;
    margin-top: 2rem;
  }

  .stat-card {
    background: var(--card-bg);
    padding: 1.5rem;
    border-radius: 12px;
    border: 1px solid var(--border);
    text-align: center;
  }

  .stat-number {
    font-size: 2rem;
    font-weight: 800;
    background: var(--gradient-text);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .stat-label {
    color: var(--text-muted);
    font-size: 0.875rem;
    margin-top: 0.25rem;
  }

  /* Contact Page Layout */
  .contact-grid {
    display: grid;
    grid-template-columns: 1fr 1.2fr;
    gap: 3.5rem;
  }

  .contact-info {
    display: flex;
    flex-direction: column;
    gap: 2rem;
  }

  .info-item {
    display: flex;
    gap: 1.25rem;
    align-items: flex-start;
  }

  .info-icon {
    background: var(--card-bg);
    border: 1px solid var(--border);
    width: 48px;
    height: 48px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.25rem;
    color: #38BDF8;
    flex-shrink: 0;
  }

  .info-text h4 {
    font-size: 1.1rem;
    margin-bottom: 0.25rem;
  }

  .info-text p {
    color: var(--text-muted);
    font-size: 0.95rem;
  }

  .contact-form {
    background: var(--card-bg);
    border: 1px solid var(--border);
    padding: 2.5rem;
    border-radius: 16px;
  }

  .form-group {
    margin-bottom: 1.5rem;
  }

  .form-group label {
    display: block;
    margin-bottom: 0.5rem;
    font-size: 0.9rem;
    color: var(--text-main);
  }

  .form-control {
    width: 100%;
    padding: 0.85rem 1rem;
    background: rgba(15, 23, 42, 0.6);
    border: 1px solid var(--border);
    border-radius: 8px;
    color: var(--text-main);
    font-size: 0.95rem;
    outline: none;
    transition: border-color 0.2s;
  }

  .form-control:focus {
    border-color: #4F46E5;
  }

  textarea.form-control {
    resize: vertical;
    min-height: 120px;
  }

  /* Footer */
  .footer {
    background: #090D16;
    border-top: 1px solid var(--border);
    padding: 4rem 5% 2rem;
  }

  .footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1.5fr;
    gap: 3rem;
    max-width: 1280px;
    margin: 0 auto 3rem;
  }

  .footer-col p {
    color: var(--text-muted);
    margin-top: 1rem;
    font-size: 0.95rem;
    max-width: 300px;
  }

  .footer-title {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 1.25rem;
    color: var(--text-main);
  }

  .footer-links {
    list-style: none;
  }

  .footer-links li {
    margin-bottom: 0.75rem;
  }

  .footer-links button {
    background: none;
    border: none;
    color: var(--text-muted);
    cursor: pointer;
    font-size: 0.95rem;
    transition: color 0.2s;
  }

  .footer-links button:hover {
    color: var(--text-main);
  }

  .footer-bottom {
    text-align: center;
    border-top: 1px solid rgba(255, 255, 255, 0.05);
    padding-top: 2rem;
    color: var(--text-muted);
    font-size: 0.875rem;
  }

  /* Responsive Design */
  @media (max-width: 900px) {
    .hero-title { font-size: 2.5rem; }
    .about-grid, .contact-grid, .footer-grid { grid-template-columns: 1fr; }
    .nav-links { display: none; }
  }
`;

export default function Home() {
  const [currentPage, setCurrentPage] = useState('home');
  const [formData, setFormData] = useState({ name: '', email: '', service: 'Web Development', message: '' });
  const [formSubmitted, setFormSubmitted] = useState(false);

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setFormSubmitted(true);
    setTimeout(() => {
      setFormSubmitted(false);
      setFormData({ name: '', email: '', service: 'Web Development', message: '' });
    }, 4000);
  };

  return (
    <div>
      {/* Inject Embedded Styles */}
      <style>{styles}</style>

      {/* HEADER / NAVIGATION */}
      <header className="navbar">
        <div className="brand-logo" onClick={() => setCurrentPage('home')}>
          ⚡ VIGHNEX <span>TECHNOLOGIES</span>
        </div>
        <ul className="nav-links">
          <li>
            <button 
              className={`nav-btn ${currentPage === 'home' ? 'active' : ''}`} 
              onClick={() => setCurrentPage('home')}
            >
              Home
            </button>
          </li>
          <li>
            <button 
              className={`nav-btn ${currentPage === 'services' ? 'active' : ''}`} 
              onClick={() => setCurrentPage('services')}
            >
              Services
            </button>
          </li>
          <li>
            <button 
              className={`nav-btn ${currentPage === 'about' ? 'active' : ''}`} 
              onClick={() => setCurrentPage('about')}
            >
              About Us
            </button>
          </li>
          <li>
            <button 
              className={`nav-btn ${currentPage === 'contact' ? 'active' : ''}`} 
              onClick={() => setCurrentPage('contact')}
            >
              Contact Us
            </button>
          </li>
        </ul>
        <button className="btn-cta" onClick={() => setCurrentPage('contact')}>
          Get Started
        </button>
      </header>

      {/* DYNAMIC PAGE RENDERER */}
      {currentPage === 'home' && (
        <>
          {/* HERO SECTION */}
          <section className="hero-section">
            <span className="badge">Next-Gen Digital Solutions</span>
            <h1 className="hero-title">
              Empowering Enterprises with <br />
              <span style={{ background: 'var(--gradient-text)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
                Scalable Software Solutions
              </span>
            </h1>
            <p className="hero-subtitle">
              At Vighnex Technologies, we design modern web platforms, high-performance mobile apps, data-driven digital marketing campaigns, and resilient cloud architectures.
            </p>
            <div className="hero-buttons">
              <button className="btn-cta" onClick={() => setCurrentPage('services')}>Explore Services</button>
              <button className="btn-outline" onClick={() => setCurrentPage('contact')}>Schedule Consultation</button>
            </div>
          </section>

          {/* SERVICES OVERVIEW */}
          <section className="section-container">
            <div className="section-header">
              <h2 className="section-title">What We Specialize In</h2>
              <p className="section-subtitle">Comprehensive technical services structured to elevate your business footprint.</p>
            </div>
            <ServicesGrid />
          </section>

          {/* ABOUT BRIEF */}
          <section className="section-container" style={{ background: 'rgba(30, 41, 59, 0.4)', borderRadius: '24px' }}>
            <AboutContent onReadMore={() => setCurrentPage('about')} />
          </section>
        </>
      )}

      {currentPage === 'services' && (
        <section className="section-container">
          <div className="section-header">
            <h2 className="section-title">Our Core Capabilities</h2>
            <p className="section-subtitle">Custom software design, cloud integration, and brand growth strategies tailored to your exact industry requirements.</p>
          </div>
          <ServicesGrid detailed={true} />
        </section>
      )}

      {currentPage === 'about' && (
        <section className="section-container">
          <AboutContent full={true} />
        </section>
      )}

      {currentPage === 'contact' && (
        <section className="section-container">
          <div className="section-header">
            <h2 className="section-title">Let's Build Something Great</h2>
            <p className="section-subtitle">Reach out to our engineering and design teams. We are ready to turn your concept into reliable software.</p>
          </div>
          <ContactForm 
            formData={formData} 
            handleInputChange={handleInputChange} 
            handleSubmit={handleSubmit} 
            formSubmitted={formSubmitted} 
          />
        </section>
      )}

      {/* FOOTER */}
      <footer className="footer">
        <div className="footer-grid">
          <div className="footer-col">
            <div className="brand-logo">
              ⚡ VIGHNEX <span>TECHNOLOGIES</span>
            </div>
            <p>Building high-performance tech products that scale seamlessly. Web, Mobile, Cloud, and Digital Growth.</p>
          </div>
          <div className="footer-col">
            <h4 className="footer-title">Navigation</h4>
            <ul className="footer-links">
              <li><button onClick={() => setCurrentPage('home')}>Home</button></li>
              <li><button onClick={() => setCurrentPage('about')}>About Us</button></li>
              <li><button onClick={() => setCurrentPage('services')}>Services</button></li>
              <li><button onClick={() => setCurrentPage('contact')}>Contact Us</button></li>
            </ul>
          </div>
          <div className="footer-col">
            <h4 className="footer-title">Services</h4>
            <ul className="footer-links">
              <li><button onClick={() => setCurrentPage('services')}>Web Development</button></li>
              <li><button onClick={() => setCurrentPage('services')}>App Development</button></li>
              <li><button onClick={() => setCurrentPage('services')}>Cloud Infrastructure</button></li>
              <li><button onClick={() => setCurrentPage('services')}>Digital Marketing</button></li>
            </ul>
          </div>
          <div className="footer-col">
            <h4 className="footer-title">Get In Touch</h4>
            <p style={{ color: 'var(--text-muted)', fontSize: '0.9rem' }}>
              Have questions? Send us an inquiry to get started on your upcoming project.
            </p>
          </div>
        </div>
        <div className="footer-bottom">
          <p>&copy; {new Date().getFullYear()} Vighnex Technologies. All rights reserved.</p>
        </div>
      </footer>
    </div>
  );
}

// Sub-Component: Services Grid
function ServicesGrid() {
  const services = [
    {
      icon: "🌐",
      title: "Web Development",
      description: "Custom frontend & backend web applications built with React, Node, and enterprise databases for speed, security, and search optimization."
    },
    {
      icon: "📱",
      title: "App Development",
      description: "Cross-platform mobile apps for iOS and Android engineered using React Native to deliver fluid UI and real-time backend synchronization."
    },
    {
      icon: "📈",
      title: "Digital Marketing",
      description: "Data-driven SEO, PPC campaigns, brand identity strategies, and conversion rate optimizations to scale user acquisition effectively."
    },
    {
      icon: "☁️",
      title: "Cloud Development",
      description: "Modern cloud-native deployment, microservices, AWS/PostgreSQL integrations, DevOps automation, and robust database architectures."
    }
  ];

  return (
    <div className="services-grid">
      {services.map((item, index) => (
        <div key={index} className="service-card">
          <div className="service-icon">{item.icon}</div>
          <h3>{item.title}</h3>
          <p>{item.description}</p>
        </div>
      ))}
    </div>
  );
}

// Sub-Component: About Content
function AboutContent({ full, onReadMore }) {
  return (
    <div className="about-grid">
      <div className="about-content">
        <span className="badge">Who We Are</span>
        <h2>Engineering Quality & Driving Innovation at Vighnex</h2>
        <p>
          Vighnex Technologies is a technology solutions agency focused on bringing real engineering expertise to digital transformation. 
          We bridge the gap between creative design, complex database designs, and clean software development.
        </p>
        <p>
          Whether building REST APIs, multi-platform applications, or modernizing backend enterprise platforms, 
          our team ensures reliability, clean design patterns, and high efficiency.
        </p>
        {!full && (
          <button className="btn-outline" onClick={onReadMore} style={{ marginTop: '1rem' }}>
            Learn More About Us
          </button>
        )}
      </div>
      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-number">99.9%</div>
          <div className="stat-label">Uptime Guarantees</div>
        </div>
        <div className="stat-card">
          <div className="stat-number">100+</div>
          <div className="stat-label">Projects Engineered</div>
        </div>
        <div className="stat-card">
          <div className="stat-number">24/7</div>
          <div className="stat-label">System Monitoring</div>
        </div>
        <div className="stat-card">
          <div className="stat-number">10x</div>
          <div className="stat-label">Performance Scaling</div>
        </div>
      </div>
    </div>
  );
}

// Sub-Component: Contact Form
function ContactForm({ formData, handleInputChange, handleSubmit, formSubmitted }) {
  return (
    <div className="contact-grid">
      <div className="contact-info">
        <h3>Contact Information</h3>
        <p style={{ color: 'var(--text-muted)' }}>
          Fill out the form or get in touch with our team directly. We review all technical requirements and respond within 24 hours.
        </p>
        
        <div className="info-item">
          <div className="info-icon">📍</div>
          <div className="info-text">
            <h4>Headquarters</h4>
            <p>Tech Hub Complex, High-Tech City, Hyderabad, TG</p>
          </div>
        </div>

        <div className="info-item">
          <div className="info-icon">✉️</div>
          <div className="info-text">
            <h4>Email Us</h4>
            <p>contact@vighnextechnologies.com</p>
          </div>
        </div>

        <div className="info-item">
          <div className="info-icon">📞</div>
          <div className="info-text">
            <h4>Call Us</h4>
            <p>+91 (800) 555-0199</p>
          </div>
        </div>
      </div>

      <form className="contact-form" onSubmit={handleSubmit}>
        {formSubmitted ? (
          <div style={{ padding: '2rem', textAlign: 'center', color: '#38BDF8' }}>
            <h3>Thank You!</h3>
            <p style={{ color: 'var(--text-muted)', marginTop: '0.5rem' }}>
              Your message has been received. Our team will contact you shortly.
            </p>
          </div>
        ) : (
          <>
            <div className="form-group">
              <label>Full Name</label>
              <input 
                type="text" 
                name="name" 
                className="form-control" 
                placeholder="Enter your name" 
                value={formData.name} 
                onChange={handleInputChange} 
                required 
              />
            </div>
            <div className="form-group">
              <label>Email Address</label>
              <input 
                type="email" 
                name="email" 
                className="form-control" 
                placeholder="name@company.com" 
                value={formData.email} 
                onChange={handleInputChange} 
                required 
              />
            </div>
            <div className="form-group">
              <label>Required Service</label>
              <select 
                name="service" 
                className="form-control" 
                value={formData.service} 
                onChange={handleInputChange}
              >
                <option value="Web Development">Web Development</option>
                <option value="App Development">App Development</option>
                <option value="Digital Marketing">Digital Marketing</option>
                <option value="Cloud Development">Cloud Development</option>
              </select>
            </div>
            <div className="form-group">
              <label>Project Details</label>
              <textarea 
                name="message" 
                className="form-control" 
                placeholder="Tell us about your requirements..." 
                value={formData.message} 
                onChange={handleInputChange} 
                required
              />
            </div>
            <button type="submit" className="btn-cta" style={{ width: '100%' }}>
              Send Message
            </button>
          </>
        )}
      </form>
    </div>
  );
}
